cat << 'EOF' > /app/generate_chart.py
import json
import os

with open('/app/benchmark/source_data.json', 'r') as f:
    data = json.load(f)

airports = data['airports']['data']

# Group by region
datasets = {}
regions = {
    "North America": "#2B5C8F",
    "Europe": "#DF7242",
    "Asia-Pacific": "#2A897A",
    "Middle East": "#B49B44",
    "Latin America": "#8D4A71",
    "Africa": "#808080"
}

for item in airports:
    reg = item['region']
    if reg not in datasets:
        datasets[reg] = []

    # Scale routes to radius (r)
    # routes range: 95 to 370. 
    # let's say r = (routes / 370) * 20 + 5 
    # Chart.js r is the radius in pixels.
    r = (item['routes'] / 10) # 9.5 to 37, maybe too big? 
    # let's do Math.sqrt(routes)*1.2

    datasets[reg].append({
        'x': item['throughput_million'],
        'y': item['on_time_rate'],
        'r': item['routes'] / 15,
        'airport': item['airport'],
        'routes': item['routes']
    })

chart_datasets = []
for reg, points in datasets.items():
    chart_datasets.append({
        'label': reg,
        'data': points,
        'backgroundColor': regions.get(reg, '#ccc') + 'B3', # 70% opacity
        'borderColor': regions.get(reg, '#ccc'),
        'borderWidth': 1
    })

# Important points to label
labels_to_show = ["Dubai (DXB)", "Tokyo Haneda (HND)", "Atlanta (ATL)"]

html = f"""<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>Airport Throughput vs Punctuality</title>
    <script src="file:///app/libs/chart.js"></script>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono&display=swap');

        body {{
            margin: 0;
            padding: 40px;
            font-family: 'IBM Plex Sans', sans-serif;
            background-color: #faf7f5;
            color: #2d3748;
        }}
        .ve-card {{
            background: #ffffff;
            border-radius: 8px;
            padding: 30px;
            box-shadow: 0 4px 6px rgba(0,0,0,0.05), 0 10px 15px rgba(0,0,0,0.02);
            border: 1px solid rgba(0,0,0,0.08);
            max-width: 900px;
            margin: 0 auto;
        }}
        h1 {{
            font-size: 24px;
            font-weight: 600;
            margin-top: 0;
            margin-bottom: 8px;
            color: #1a202c;
        }}
        .subtitle {{
            font-size: 14px;
            color: #718096;
            margin-bottom: 24px;
            font-weight: 400;
        }}
        .chart-container {{
            position: relative;
            height: 500px;
            width: 100%;
        }}
    </style>
</head>
<body>
    <div class="ve-card" id="card">
        <h1>Global Airport Performance</h1>
        <div class="subtitle">Passenger Throughput vs. On-Time Performance (Bubble Size = Number of Routes)</div>
        <div class="chart-container">
            <canvas id="myChart"></canvas>
        </div>
    </div>

    <script>
        const ctx = document.getElementById('myChart').getContext('2d');

        const labelsPlugin = {{
            id: 'labelsPlugin',
            afterDraw(chart) {{
                const ctx = chart.ctx;
                ctx.save();
                ctx.font = '600 12px "IBM Plex Sans"';
                ctx.textBaseline = 'middle';

                chart.data.datasets.forEach((dataset, i) => {{
                    const meta = chart.getDatasetMeta(i);
                    dataset.data.forEach((datapoint, index) => {{
                        if (["Dubai (DXB)", "Tokyo Haneda (HND)", "Atlanta (ATL)"].includes(datapoint.airport)) {{
                            const model = meta.data[index];
                            ctx.fillStyle = '#1a202c';

                            // Adjust text position
                            let xOffset = model.options.radius + 6;
                            let yOffset = 0;

                            if (datapoint.airport === "Atlanta (ATL)") {{
                                ctx.textAlign = 'right';
                                xOffset = -model.options.radius - 6;
                                yOffset = 0;
                            }} else if (datapoint.airport === "Dubai (DXB)") {{
                                ctx.textAlign = 'left';
                                yOffset = -model.options.radius - 6;
                                xOffset = 0;
                            }} else {{
                                ctx.textAlign = 'left';
                            }}

                            // Draw background pill
                            const text = datapoint.airport;
                            const textWidth = ctx.measureText(text).width;
                            const padX = 6, padY = 4;

                            let bgX = model.x + xOffset;
                            let bgY = model.y + yOffset;

                            if (ctx.textAlign === 'right') {{
                                bgX -= textWidth;
                            }} else if (ctx.textAlign === 'center') {{
                                bgX -= textWidth/2;
                            }}

                            ctx.fillStyle = 'rgba(255,255,255,0.85)';
                            ctx.beginPath();
                            ctx.roundRect(bgX - padX, bgY - 12/2 - padY, textWidth + padX*2, 12 + padY*2, 4);
                            ctx.fill();
                            ctx.strokeStyle = '#e2e8f0';
                            ctx.stroke();

                            ctx.fillStyle = '#1a202c';
                            ctx.fillText(text, model.x + xOffset, model.y + yOffset);

                            // Draw connecting line if needed
                            /*
                            ctx.beginPath();
                            ctx.moveTo(model.x, model.y);
                            ctx.lineTo(model.x + xOffset/2, model.y + yOffset/2);
                            ctx.strokeStyle = '#a0aec0';
                            ctx.stroke();
                            */
                        }}
                    }});
                }});
                ctx.restore();
            }}
        }};

        new Chart(ctx, {{
            type: 'bubble',
            data: {{
                datasets: {json.dumps(chart_datasets)}
            }},
            options: {{
                responsive: true,
                maintainAspectRatio: false,
                plugins: {{
                    legend: {{
                        position: 'right',
                        labels: {{
                            usePointStyle: true,
                            font: {{
                                family: "'IBM Plex Sans', sans-serif",
                                size: 12
                            }}
                        }}
                    }},
                    tooltip: {{
                        callbacks: {{
                            label: function(context) {{
                                const d = context.raw;
                                return d.airport + ': ' + d.x + 'M pax, ' + d.y + '% on-time, ' + d.routes + ' routes';
                            }}
                        }},
                        backgroundColor: 'rgba(26, 32, 44, 0.9)',
                        titleFont: {{ family: "'IBM Plex Sans', sans-serif" }},
                        bodyFont: {{ family: "'IBM Plex Sans', sans-serif" }},
                        padding: 10,
                        cornerRadius: 6
                    }}
                }},
                scales: {{
                    x: {{
                        title: {{
                            display: true,
                            text: 'Annual Passenger Throughput (Millions)',
                            font: {{ family: "'IBM Plex Sans', sans-serif", weight: 500 }}
                        }},
                        grid: {{
                            color: '#edf2f7',
                            drawBorder: false
                        }},
                        min: 0,
                        max: 100
                    }},
                    y: {{
                        title: {{
                            display: true,
                            text: 'On-Time Performance (%)',
                            font: {{ family: "'IBM Plex Sans', sans-serif", weight: 500 }}
                        }},
                        grid: {{
                            color: '#edf2f7',
                            drawBorder: false
                        }},
                        min: 65,
                        max: 95
                    }}
                }},
                animation: false
            }},
            plugins: [labelsPlugin]
        }});
    </script>
</body>
</html>
"""

with open('/app/output/chart.html', 'w') as f:
    f.write(html)
